#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
using namespace std;

typedef pair<int, pair<int, int>> State;

const int INF = 1 << 29;
const int MAXN = 500;

struct Edge {
    int src, dest, capacity, flow;
};

bool grid[11][11];
vector<int> adj[MAXN];
vector<Edge> edges;
int dist[MAXN], pt[MAXN], size, exit_r, exit_c, time_limit, steps[11][11], caps[11][11];

int bfs_distance(int x1, int y1, int x2, int y2) {
    queue<State> q;
    q.push({0, {x1, y1}});
    int dist_map[11][11];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            dist_map[i][j] = INF;
    while (!q.empty()) {
        int cost = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        dist_map[r][c] = cost;
        if (r > 0 && grid[r-1][c]) {
            int nr = r-1, nc = c;
            if (dist_map[nr][nc] > cost + 1) {
                bool cond1 = (nr == x2 && nc == y2 && steps[nr][nc] >= cost + 1);
                bool cond2 = (!(nr == x2 && nc == y2) && steps[nr][nc] > cost + 1);
                if (cond1 || cond2)
                    q.push({cost + 1, {nr, nc}});
            }
        }
        if (c > 0 && grid[r][c-1]) {
            int nr = r, nc = c-1;
            if (dist_map[nr][nc] > cost + 1) {
                bool cond1 = (nr == x2 && nc == y2 && steps[nr][nc] >= cost + 1);
                bool cond2 = (!(nr == x2 && nc == y2) && steps[nr][nc] > cost + 1);
                if (cond1 || cond2)
                    q.push({cost + 1, {nr, nc}});
            }
        }
        if (r < size-1 && grid[r+1][c]) {
            int nr = r+1, nc = c;
            if (dist_map[nr][nc] > cost + 1) {
                bool cond1 = (nr == x2 && nc == y2 && steps[nr][nc] >= cost + 1);
                bool cond2 = (!(nr == x2 && nc == y2) && steps[nr][nc] > cost + 1);
                if (cond1 || cond2)
                    q.push({cost + 1, {nr, nc}});
            }
        }
        if (c < size-1 && grid[r][c+1]) {
            int nr = r, nc = c+1;
            if (dist_map[nr][nc] > cost + 1) {
                bool cond1 = (nr == x2 && nc == y2 && steps[nr][nc] >= cost + 1);
                bool cond2 = (!(nr == x2 && nc == y2) && steps[nr][nc] > cost + 1);
                if (cond1 || cond2)
                    q.push({cost + 1, {nr, nc}});
            }
        }
    }
    return dist_map[x2][y2];
}

void insert_edge(int s, int d, int cap) {
    edges.push_back({s, d, cap, 0});
    edges.push_back({d, s, 0, 0});
    adj[s].push_back((int)edges.size() - 2);
    adj[d].push_back((int)edges.size() - 1);
}

bool level_graph() {
    queue<int> q;
    q.push(0);
    memset(dist, -1, (size * size * 2 + 2) * sizeof(dist[0]));
    dist[0] = 0;
    while (!q.empty() && dist[size * size * 2 + 1] == -1) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            int v = edges[id].dest;
            if (dist[v] == -1 && edges[id].flow < edges[id].capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[size * size * 2 + 1] != -1;
}

int blocking_flow(int u, int bottleneck) {
    if (!bottleneck) return 0;
    if (u == size * size * 2 + 1) return bottleneck;
    for (; pt[u] < (int)adj[u].size(); ++pt[u]) {
        int id = adj[u][pt[u]];
        int v = edges[id].dest;
        if (dist[v] != dist[u] + 1) continue;
        int pushed = blocking_flow(v, min(bottleneck, edges[id].capacity - edges[id].flow));
        if (pushed) {
            edges[id].flow += pushed;
            edges[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int dinic() {
    int total = 0;
    while (level_graph()) {
        memset(pt, 0, (size * size * 2 + 2) * sizeof(pt[0]));
        int f;
        while ((f = blocking_flow(0, INF)) > 0)
            total += f;
    }
    return total;
}

int main() {
    cin >> size >> time_limit;
    queue<State> q;
    char ch;
    int idx = 1;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            cin >> ch;
            steps[i][j] = time_limit;
            if (ch == 'Z') {
                exit_r = i; exit_c = j;
                grid[i][j] = false;
            } else if (ch == 'Y') {
                grid[i][j] = false;
            } else {
                grid[i][j] = true;
            }
            insert_edge(0, idx++, (ch == 'Z' || ch == 'Y') ? 0 : ch - 48);
        }
    }
    idx = size * size + 1;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            cin >> ch;
            if (ch >= '0' && ch <= '9') caps[i][j] = ch - 48;
            insert_edge(idx++, size * size * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - 48);
        }
    }
    q.push({0, {exit_r, exit_c}});
    while (!q.empty()) {
        int cost = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        steps[r][c] = cost;
        if (r > 0 && cost + 1 < steps[r - 1][c] && grid[r - 1][c])
            q.push({cost + 1, {r - 1, c}});
        if (c > 0 && cost + 1 < steps[r][c - 1] && grid[r][c - 1])
            q.push({cost + 1, {r, c - 1}});
        if (r < size - 1 && cost + 1 < steps[r + 1][c] && grid[r + 1][c])
            q.push({cost + 1, {r + 1, c}});
        if (c < size - 1 && cost + 1 < steps[r][c + 1] && grid[r][c + 1])
            q.push({cost + 1, {r, c + 1}});
    }
    int node = 0;
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            int sink = size * size;
            node++;
            for (int x = 0; x < size; ++x) {
                for (int y = 0; y < size; ++y) {
                    sink++;
                    if (grid[i][j] && grid[x][y] && bfs_distance(i, j, x, y) <= time_limit)
                        insert_edge(node, sink, INF);
                }
            }
        }
    }
    cout << dinic() << endl;
    return 0;
}
